};

std::string markdownToHtml(const std::string& markdown) {
    std::string html;

    // Replace Markdown text with corresponding HTML
    std::string::const_iterator it = markdown.begin();
    while (it != markdown.end()) {
        std::string::const_iterator end = std::search(it, markdown.end(), std::begin(MARKDOWN_TO_HTML_RULES), std::end(MARKDOWN_TO_HTML_RULES),
            [](const std::string::const_iterator& it, const std::unordered_map<std::string, std::string>::const_iterator& rule) {
