        if (end == markdown.end()) {
            html += std::string(it, markdown.end());
            break;
        }

        std::string match = std::string(it, end);
        html += MARKDOWN_TO_HTML_RULES[match](std::begin(match), std::end(match));
        it = end + match.size();
    }

    return html;
}

int main() {
